# AUTO-GENERATED by _add_compatibility_api.py
"""Compatibility result → language-ready response."""
from app.services.content.loader import load_labels, load_pack


def _grade_label(lang: str, grade: str) -> str:
    try:
        table = load_labels(lang)["GRADE_LABELS"]
    except (KeyError, TypeError):
        return grade
    return table.get(grade, grade)


def _write_axis(axis_data: dict, content_map: dict, relationship_type: str) -> dict:
    tag = axis_data.get("tag", "MIXED")
    # 관계 유형(romance/business)에 따른 서브 맵 가져오기
    rel_map = content_map.get(relationship_type, {})
    content = rel_map.get(tag) or rel_map.get("DEFAULT", {})
    signature = content_map.get("__signature__", "")
    
    body = content.get("body", "")
    if signature and body:
        body = f"{signature} {body}"
    
    out = {
        "score": axis_data["score"],
        "grade": axis_data["grade"],
        "tag": tag,
        "headline": content.get("headline", ""),
        "body": body,
    }
    if axis_data.get("shared"):
        out["shared"] = axis_data["shared"]
    if axis_data.get("breakdown"):
        out["breakdown"] = axis_data["breakdown"]
    return out


def write_compatibility(compat: dict, lang: str = "en", relationship_type: str = "romance") -> dict:
    pack = load_pack(lang, "compatibility")
    overall = compat["overall"]
    _overall_all = pack.get("OVERALL_CONTENT", {})

    # NEUTRAL 등급이면 score 기반으로 variants 중 하나 선택 (반복 방지)
    if overall["grade"] == "NEUTRAL" and _overall_all.get("NEUTRAL_VARIANTS"):
        variants = _overall_all["NEUTRAL_VARIANTS"]
        try:
            # score: -1.0 ~ 1.0 → 0~100으로 변환
            s = (float(overall["score"]) + 1) / 2 * 100
        except (TypeError, ValueError):
            s = 50.0
        n = len(variants)
        idx = min(n - 1, max(0, int(round(s) * n // 100)))  # 표시 반올림과 정확히 일치
        overall_content = variants[idx]
    else:
        overall_content = _overall_all.get(overall["grade"]) or _overall_all.get("NEUTRAL", {})
    if not overall_content.get("headline"):
        # Defensive fallback: pack 이 비어있거나 예상 밖 grade 일 때
        try:
            fb = load_labels(lang).get("COMPAT_FALLBACK_HEADLINE", "")
        except (KeyError, TypeError):
            fb = ""
        overall_content = {"headline": fb, "body": ""}

    # 👇 관계 유형별 맞춤 조언 추가
    rel_pack = pack.get("RELATIONSHIP_CONTENT", {}).get(relationship_type, {})
    tips_by_band = rel_pack.get("tips_by_band") or {}
    try:
        _s = (float(overall["score"]) + 1) / 2 * 100
    except (TypeError, ValueError):
        _s = 50.0
    if _s < 45:
        _band = "low"
    elif _s < 65:
        _band = "mid"
    else:
        _band = "high"
    relationship_advice = tips_by_band.get(_band) or rel_pack.get("tip", "")

    return {
        "meta": {
            "lang": lang,
            "schema_version": "1.0",
            "relationship_type": relationship_type,
        },
        "axes": {
            "elements": _write_axis(compat["axes"]["elements"], pack.get("ELEMENT_CONTENT", {}), relationship_type),
            "day_master": _write_axis(compat["axes"]["day_master"], pack.get("DAY_MASTER_CONTENT", {}), relationship_type),
            "ten_gods": _write_axis(compat["axes"]["ten_gods"], pack.get("TEN_GODS_CONTENT", {}), relationship_type),
            "sinsal": _write_axis(compat["axes"]["sinsal"], pack.get("SINSAL_CONTENT", {}), relationship_type),
        },
        "overall": {
            "score": overall["score"],
            "grade": overall["grade"],
            "grade_label": _grade_label(lang, overall["grade"]),
            "headline": overall_content.get("headline", ""),
            "body": overall_content.get("body", ""),
        },
        "disclaimer": pack.get("DISCLAIMER", ""),
        "relationship_advice": relationship_advice,
    }
